#!/usr/bin/env bash
# =============================================================================
# =============================================================================
# InstantGram v1.25.0  -  peek, super hearts, 6 pins, profile-only posts
#
#   * Peek: hold a chat in the inbox > "Peek (no Seen)". Read it without
#     the other person getting "Seen".
#   * Super hearts: hold the heart on a post or clip. One per person per
#     post; it also likes. Purple heart + count, and the author is told.
#   * Pin up to 6 posts (was 3).
#   * Only on my profile: a switch when posting (and in the post menu).
#     Such posts stay out of Home, Clips, Explore and search.
#
# Run from the project root:   bash update_v1250_peek_hearts.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="ccf9045e1229c2d2052943a51b841041930db568cbb729cb269174ba5fd4c933"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/services/highlight_service.dart ] || { echo "ERROR: v1.24.0 is not installed. Run update_v1240_highlights.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
# Some browsers save this file with Windows line endings (CRLF). Those
# extra characters corrupt the payload, so strip any control character
# sitting at the end of a line before decoding.
awk '/^__PAYLOAD__/{f=1;next} /^#/{f=0} f' "$0" | sed 's/[[:cntrl:]]*$//' | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       expected  $EXPECTED_SHA256"
  echo "       actual    $ACTUAL"
  echo "       your file is $(wc -c < "$0") bytes; it should be 1674263 bytes."
  echo "       Smaller size = the download was cut short: download it again."
  echo "       Same size but still failing, run:"
  echo "         sed -i 's/[[:cntrl:]]*$//' $(basename "$0") && bash $(basename "$0")"
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh tools/delete_user.sh tools/push_setup.sh tools/publish_rules.sh 2>/dev/null || true
# keys for the delete tool live in ~/.instantgram-admin, never in the project
touch .gitignore
for p in '*firebase-adminsdk*.json' '__pycache__/'; do
  grep -qxF "$p" .gitignore || echo "$p" >> .gitignore
done
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
if ! grep -qE "^[[:space:]]+firebase_messaging:" pubspec.yaml; then
  echo "==> Adding firebase_messaging..."
  flutter pub add firebase_messaging || { echo "ERROR: could not add firebase_messaging (internet?). Run: flutter pub add firebase_messaging"; exit 1; }
fi

echo ""
echo "==> Adding the moment fonts to pubspec.yaml..."
python3 - pubspec.yaml <<'PYFONTS'
import re, sys
p = sys.argv[1] if len(sys.argv) > 1 else "pubspec.yaml"
s = open(p).read()
fams = [("Bebas", "BebasNeue-Regular.ttf"), ("Marker", "PermanentMarker-Regular.ttf"),
        ("Lobster", "Lobster-Regular.ttf"), ("Caveat", "Caveat-Variable.ttf"),
        ("Playfair", "PlayfairDisplay-Variable.ttf"), ("SpaceMono", "SpaceMono-Bold.ttf")]
add = ""
for fam, file in fams:
    if not re.search(r"family:\s*" + fam + r"\s*$", s, re.M):
        add += "    - family: %s\n      fonts:\n        - asset: assets/fonts/%s\n" % (fam, file)
if add:
    m = re.search(r"^  fonts:[ \t]*\r?\n", s, re.M)
    if m:
        s = s[:m.end()] + add + s[m.end():]
    else:
        m2 = re.search(r"^  uses-material-design:[ \t]*true[ \t]*\r?\n", s, re.M) or re.search(r"^flutter:[ \t]*\r?\n", s, re.M)
        if not m2:
            sys.exit("ERROR: no flutter: section in pubspec.yaml")
        s = s[:m2.end()] + "  fonts:\n" + add + s[m2.end():]
    open(p, "w").write(s)
    print("    pubspec.yaml: added the moment text fonts")
PYFONTS

echo "Done. v1.25.0 is in place."
echo ""
echo "After the git push, run: bash tools/publish_rules.sh"
exit 0

